import { Mesh, Group, PlaneGeometry, CircleGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, Color, DirectionalLight, AmbientLight, PerspectiveCamera } from 'three/webgpu';
import { vec3, mix, smoothstep, uv, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, CircleGeometry, DirectionalLight, AmbientLight, Color, DoubleSide } = THREE;

  const group = new Group();
  group.name = 'nova-atelier-watch-hero';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // --- Backdrop plane with vertical gradient (7x6 at z=-2.5) ---
  const stops = config.intent?.visualSpec?.colors?.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.55, hex: '#101017' },
    { at: 1, hex: '#16161d' }
  ];
  const c0 = new THREE.Color(stops[0].hex);
  const c1 = new THREE.Color(stops[Math.min(1, stops.length - 1)]?.hex ?? '#101017');
  const c2 = new THREE.Color(stops[stops.length - 1].hex);

  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  const v = uv().y; // 0 bottom -> 1 top
  const t1 = uniform(stops[1] ? stops[1].at : 0.55);
  const colA = uniform(c0);
  const colB = uniform(c1);
  const colC = uniform(c2);
  const step1 = smoothstep(t1.sub(0.02), t1.add(0.02), v);
  const step2 = smoothstep(float(0.98), float(1.0), v);
  let blended = mix(colA, colB, step1);
  blended = mix(blended, colC, smoothstep(t1, float(1.0), v));
  backdropMat.colorNode = blended;

  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // --- Contact shadow plane (radial, radius 1.6, opacity 0.55) ---
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const suv = uv();
  const d = suv.sub(0.5).length().mul(2.0);
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = smoothstep(float(1.0), float(0.0), d).mul(0.55);
  const shadowPlane = new Mesh(new CircleGeometry(1.6, 64), shadowMat);
  shadowPlane.rotation.x = -Math.PI / 2;
  shadowPlane.position.set(0, -1.22, 0);
  group.add(shadowPlane);

  // --- Plinth (cylindrical, radius 1.4, height 0.25, top at y=-1.1) ---
  const plinthGeo = new THREE.CylinderGeometry(1.4, 1.4, 0.25, 64, 1, false);
  const plinthMat = new MeshStandardNodeMaterial({
    color: new Color('#14141a'),
    roughness: 0.7,
    metalness: 0.3
  });
  const plinth = new Mesh(plinthGeo, plinthMat);
  plinth.position.set(0, -1.225, 0); // top at -1.1
  group.add(plinth);

  // --- Accent rim light (signal red, grazing left flank) ---
  const accentLight = new DirectionalLight(new Color('#ff2a38'), 1.5);
  accentLight.position.set(-3.5, 0.2, 1.0);
  accentLight.target.position.set(0, 0, 0);
  group.add(accentLight);
  group.add(accentLight.target);

  // --- Back rim light ---
  const backRim = new DirectionalLight(new Color('#e8ecf2'), 0.8);
  backRim.position.set(2.0, 1.5, -2.0);
  backRim.target.position.set(0, 0, 0);
  group.add(backRim);
  group.add(backRim.target);

  // --- Hero subject group (for watch mesh + orbit) ---
  const heroGroup = new Group();
  heroGroup.position.set(0, 0, 0);
  group.add(heroGroup);

  // --- Text content ---
  const textObjects = [];
  let headlineY = -1.5; // headline baseline 1.5 units below scene center
  let bodyY = headlineY - 0.5;
  let captionY = bodyY - 0.4;

  for (const item of items) {
    const role = item.role;
    const fontSize = item.typography?.fontSize ?? 26;
    let align = 'center';
    let color = '#e8ecf2';
    let letterSpacing = 0;
    let y = bodyY;
    if (role === 'headline') {
      color = '#e8ecf2';
      y = headlineY;
      letterSpacing = -0.005 * fontSize;
    } else if (role === 'body') {
      color = '#e8ecf2';
      y = bodyY;
    } else if (role === 'caption') {
      color = '#ff2a38';
      y = captionY;
      letterSpacing = 0.08 * fontSize;
    }
    const t = ctx.fontAtlas.createText(String(item.text), {
      fontSize,
      color,
      align,
      letterSpacingPx: letterSpacing
    });
    t.position.set(0, y, 0.2);
    group.add(t);
    textObjects.push(t);
  }

  // --- Load GLB and apply PBR ---
  let watchMesh = null;
  const cleanupCollectors = [];
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const scene = gltf.scene ?? gltf;
      scene.traverse((child) => {
        if (child.isMesh) {
          child.material = new MeshStandardNodeMaterial({
            color: new Color('#9a9aa2'),
            roughness: 0.52,
            metalness: 0.55,
            clearcoat: 0.2,
            clearcoatRoughness: 0.4
          });
        }
      });
      // Normalize to 2.2 units tall
      const box = new THREE.Box3().setFromObject(scene);
      const size = new THREE.Vector3();
      box.getSize(size);
      const scale = 2.2 / size.y;
      scene.scale.setScalar(scale);
      const center = new THREE.Vector3();
      box.getCenter(center);
      scene.position.sub(center.multiplyScalar(scale));
      // Rest on plinth top: bottom at y=-1.1
      const nbox = new THREE.Box3().setFromObject(scene);
      const nsize = new THREE.Vector3();
      nbox.getSize(nsize);
      scene.position.y += -1.1 - nbox.min.y + 0.02;
      heroGroup.add(scene);
      watchMesh = scene;
    });
  }

  // --- Cinematic primitives ---
  const primResults = [];
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const target = (p.name === 'depth-rotate') ? (heroGroup) : heroGroup;
    try {
      const r = ctx.primitives[p.name](target, p.params || {});
      if (r) primResults.push(r);
    } catch (e) {
      // primitive may not be available; skip gracefully
    }
  }

  // --- Entrance animation ---
  const tl = gsap.timeline();
  group.scale.set(1.04, 1.04, 1.04);
  group.userData.visible = false;
  tl.to(group.scale, {
    x: 1.0, y: 1.0, z: 1.0,
    duration: 0.9,
    ease: 'power4.out'
  });
  tl.from(group.position, { y: 0.4, duration: 0.7, ease: 'power3.out' }, 0);
  for (const t of textObjects) {
    tl.from(t.position, { y: '+=0.2', opacity: 0, duration: 0.5, ease: 'power2.out' }, 0.2);
  }

  // --- Handlers ---
  group.userData.handlers = {
    click: (e) => {
      ctx.emit('navigate', { to: 'hub-collection' });
    },
    hover: (active) => {
      // depth-rotate primitive handles tilt; add press scale settle
      if (active) {
        gsap.to(heroGroup.scale, { x: 1.03, y: 1.03, z: 1.03, duration: 0.12, ease: 'back.out(2)' });
      } else {
        gsap.to(heroGroup.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.9, ease: 'power4.out' });
        gsap.to(heroGroup.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out', delay: 0.0 });
      }
    }
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    tl.kill();
    for (const r of primResults) {
      try { r.cleanup && r.cleanup(); } catch (e) {}
    }
    backdropMat.dispose();
    backdrop.geometry.dispose();
    shadowMat.dispose();
    shadowPlane.geometry.dispose();
    plinthMat.dispose();
    plinthGeo.dispose();
    if (watchMesh) {
      watchMesh.traverse((c) => {
        if (c.isMesh) {
          c.geometry?.dispose?.();
          if (c.material) {
            if (Array.isArray(c.material)) c.material.forEach(m => m.dispose?.());
            else c.material.dispose?.();
          }
        }
      });
    }
    accentLight.dispose?.();
    backRim.dispose?.();
  };

  return group;
}
